#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Off-site backups for the live VM: an rclone crypt remote over Google Drive (docs/adr/0003).
# Run on your PC, in Git Bash, from anywhere:  bash scripts/vm/setup-drive-backup.sh
# It needs the VM's SSH key and a browser on this PC. Nothing is written on the PC.

TOTAL_STAGES=4
ENV_FILE="/nonexistent/storytell-wizard.env"   # this wizard keeps nothing in a .env file

VM="${STORYTELL_VM:-ubuntu@140.245.56.181}"
KEY="${STORYTELL_VM_KEY:-$HOME/.ssh/oracle_storytell}"
PORT=53682   # rclone's sign-in port, fixed by rclone
vm()  { ssh -i "$KEY" -o ConnectTimeout=15 "$VM" "$@"; }
rc()  { vm "sudo -u storytell -H rclone $*"; }
die() { printf '\n  %s✗ %s%s\n\n' "$RED" "$1" "$RESET"; exit 1; }

banner "Storytell: off-site backups to Google Drive"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the VM"
say "Checking that this PC can reach the VM and that rclone is installed there."
[[ -f "$KEY" ]] || die "No SSH key at $KEY. Set STORYTELL_VM_KEY to its path and run again."
vm true 2>/dev/null || die "Can't reach $VM over SSH."
VERSION=$(vm "rclone version 2>/dev/null | head -1" || true)
[[ -n "$VERSION" ]] || die "rclone is not installed on the VM (sudo apt-get install rclone)."
printf '  %s✓%s %s on the VM\n' "$GREEN" "$RESET" "$VERSION"
REMOTES=$(rc listremotes 2>/dev/null || true)
HAS_DRIVE=false; HAS_CRYPT=false
# Listed and working: a sign-in that was never finished leaves a remote with no token.
if grep -qx 'gdrive:' <<<"$REMOTES" && rc 'lsd gdrive:' >/dev/null 2>&1; then HAS_DRIVE=true; fi
grep -qx 'storytell-backup:' <<<"$REMOTES" && HAS_CRYPT=true
$HAS_DRIVE && note "A Google Drive remote (gdrive:) is already set up."
$HAS_CRYPT && note "An encrypted remote (storytell-backup:) is already set up."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Sign in to Google"
if $HAS_DRIVE && ! confirm "gdrive: exists. Sign in again and replace it?"; then
  note "Keeping the Google Drive remote as it is."
else
  say "rclone on the VM will ask Google for access to the files it makes itself"
  say "(scope drive.file: it can't see anything else in your Drive)."
  printf '\n'
  step "In a moment a line appears below that starts with:"
  say "    http://127.0.0.1:$PORT/auth?state=..."
  step "Open that link in a browser ON THIS PC (Ctrl-click it, or copy and paste)."
  step "Choose the Google account that should hold the backups, then Allow."
  step "The browser says 'Success!'. Come back here; this step then finishes by itself."
  note "The link only works on this PC while this step is running."
  pause "Press Enter to start"
  printf '\n'
  # stdout (the saved settings, token included) is thrown away; the link comes on stderr.
  ssh -i "$KEY" -t -L "$PORT:127.0.0.1:$PORT" "$VM" \
    "sudo -u storytell -H rclone config create gdrive drive scope=drive.file >/dev/null" \
    || die "The sign-in didn't finish. Run the wizard again to retry."
  rc lsd gdrive: >/dev/null 2>&1 || die "Signed in, but rclone can't list the Drive. Run the wizard again."
  printf '\n  %s✓%s Google Drive is connected\n' "$GREEN" "$RESET"
  pause
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Choose the encryption passphrase and salt"
if $HAS_CRYPT; then
  warn "storytell-backup: exists. A new passphrase can't read backups made with the old one."
fi
if $HAS_CRYPT && ! confirm "Replace the passphrase and salt anyway?"; then
  note "Keeping the encrypted remote as it is."
else
  say "Backups are encrypted on the VM before they reach Drive, with two secrets:"
  say "a passphrase and a salt. Google never sees them, and neither does anyone else."
  printf '\n'
  warn "If the VM is lost, these two are the ONLY way to read the backups."
  step "Open your password manager and make an entry 'Storytell backup'."
  step "Generate two long random values there (20+ characters, letters and digits)."
  step "Save the entry FIRST, then paste each value below. Typing is hidden."
  pause "Press Enter when both are saved in your password manager"
  while true; do
    ask_secret PASSPHRASE "Passphrase:"
    ask_secret PASSPHRASE_AGAIN "Passphrase again:"
    ask_secret SALT "Salt:"
    ask_secret SALT_AGAIN "Salt again:"
    if [[ "$PASSPHRASE" != "$PASSPHRASE_AGAIN" || "$SALT" != "$SALT_AGAIN" ]]; then warn "They didn't match. Try again."; continue; fi
    if (( ${#PASSPHRASE} < 12 || ${#SALT} < 12 )); then warn "Use at least 12 characters for each. Try again."; continue; fi
    if [[ "$PASSPHRASE" == "$SALT" ]]; then warn "The salt must differ from the passphrase. Try again."; continue; fi
    break
  done
  # The two values travel on stdin and are obscured on the VM, so neither shows in a process list.
  printf '%s\n%s\n' "$PASSPHRASE" "$SALT" | vm 'sudo -u storytell -H bash -c '"'"'
    IFS= read -r P; IFS= read -r S
    OP=$(printf %s "$P" | rclone obscure -) && OS=$(printf %s "$S" | rclone obscure -) &&
    rclone config create storytell-backup crypt remote=gdrive:Storytell password="$OP" password2="$OS" --no-obscure >/dev/null
  '"'"'' || die "Couldn't save the encrypted remote on the VM."
  unset PASSPHRASE PASSPHRASE_AGAIN SALT SALT_AGAIN
  printf '  %s✓%s Encrypted remote storytell-backup: saved on the VM\n' "$GREEN" "$RESET"
  pause
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Check that only encrypted names reach Drive"
TYPES=$(rc "listremotes --long")
grep -Eq '^gdrive: +drive$' <<<"$TYPES" || die "gdrive: is missing or not a Google Drive remote."
grep -Eq '^storytell-backup: +crypt$' <<<"$TYPES" || die "storytell-backup: is missing or not a crypt remote."
rc "mkdir storytell-backup:wizard-check" || die "Couldn't write through the encrypted remote."
PLAIN=$(rc "lsf storytell-backup:" | tr -d '\r')
RAW=$(rc "lsf gdrive:Storytell" | tr -d '\r')
rc "rmdir storytell-backup:wizard-check" || true
grep -qx 'wizard-check/' <<<"$PLAIN" || die "The test folder isn't visible through the encrypted remote."
if grep -q 'wizard-check' <<<"$RAW"; then die "The folder's real name reached Drive: encryption is not on."; fi
printf '  %s✓%s Through the encrypted remote the test folder reads: wizard-check\n' "$GREEN" "$RESET"
printf '  %s✓%s On Google Drive its name is scrambled: %s\n' "$GREEN" "$RESET" "$(head -1 <<<"$RAW")"
note "The test folder is removed again."
pause

finish
say "Next: go back to Claude and say it's done."
say "It turns on BACKUP_REMOTE on the VM and runs the first off-site backup."
printf '\n'
